"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { getServerMods, installMod, uninstallMod, type CatalogMod } from "@/lib/actions-mods";

/**
 * Mod Store — the panel's differentiator. An App-Store-style browse experience
 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
 * version → confirm install flow.
 *
 * REAL backend: catalog + install state + install/uninstall come from
 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
 * (clearly labelled in the UI): star rating, install counts, screenshots,
 * version history, reviews and changelog — the GameMod model has no such fields
 * yet, so they are computed deterministically from the mod's slug so the
 * storefront feels alive. The version dropdown is display-only: the installer
 * always applies the latest compatible build (see the note in the install modal).
 *
 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
 * protection, economy, chat, permissions…), falling back to the full catalog
 * with a note when a family draws no plugin categories.
 */

const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];

// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function ratingFor(m: CatalogMod): number {
  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
}
function installsFor(m: CatalogMod): number {
  const base = 800 + (hash(m.slug) % 90000);
  return m.featured ? base * 4 + 120000 : base;
}
function fmtInstalls(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
  return String(n);
}
function versionsFor(m: CatalogMod): string[] {
  const h = hash(m.slug);
  const major = 1 + (h % 4);
  const minor = h % 12;
  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
}
function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
  const h = hash(m.slug);
  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
  return [
    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
  ];
}

type SortKey = "popular" | "rating" | "name";

export function ModStore({
  serverId,
  scope,
  onOpenPlugins,
}: {
  serverId: string;
  scope: "mods" | "plugins";
  onOpenPlugins?: () => void;
}) {
  const [mods, setMods] = useState<CatalogMod[] | null>(null);
  const [variant, setVariant] = useState<string | null>(null);
  const [installedCount, setInstalledCount] = useState(0);
  const [busy, setBusy] = useState(false);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [actErr, setActErr] = useState<string | null>(null);

  const [view, setView] = useState<"browse" | "installed">("browse");
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [sort, setSort] = useState<SortKey>("popular");
  const [detail, setDetail] = useState<CatalogMod | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await getServerMods(serverId);
    if (res.error || !res.view) {
      setLoadErr(res.error ?? "Unavailable.");
      setMods(null);
      return;
    }
    const flat = res.view.categories.flatMap((c) => c.mods);
    setMods(flat);
    setVariant(res.view.variant);
    setInstalledCount(res.view.installedCount);
    setBusy(res.view.busy);
    setLoadErr(null);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { Client, type ClientChannel } from "ssh2";
import type { Job } from "@prisma/client";

/**
 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
 * state recorded in `ServerMod` rows:
 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
 *
 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
 *
 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
 * mod is installed when nothing was written to their server:
 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
 *    FAILED with a clear reason — never silently "INSTALLED".
 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
 *    message. A change we did NOT apply is a failure and must say so.
 */

const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-mods] notify failed", e);
  }
}

export async function gameModSync(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game mod sync: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const pending = await db.serverMod.findMany({
    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
    include: { mod: true },
  });
  if (pending.length === 0) return;

  const installedNames: string[] = [];
  const removedNames: string[] = [];
  const failedNames: string[] = [];

  for (const sm of pending) {
    const removing = sm.status === "REMOVING";
    try {
      if (SANDBOX) {
        // Dev simulation — no VM mutation.
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
          installedNames.push(sm.mod.name);
        }
        continue;
      }

      if (!REAL_ENABLED) {
        // Honest failure: nothing was applied. Do NOT report success.
        await db.serverMod.update({
          where: { id: sm.id },
          data: {
            status: "FAILED",
            error:
              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
          },
        });
        failedNames.push(sm.mod.name);
        continue;
      }

      // REAL path — install/remove over SSH via the per-source adapter.
      const modRow: ModRowFull = {
        gameFamily: sm.mod.gameFamily,
        source: sm.mod.source,
        sourceId: sm.mod.sourceId,
        slug: sm.mod.slug,
        name: sm.mod.name,
        url: sm.mod.url,
        variant: server.gameVariant ?? null,
        appliesTo: sm.mod.appliesToVariant ?? null,
      };
      const result = removing ? await removeModReal(server, modRow) : await installModReal(server, modRow);

      if (result.ok) {
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({
            where: { id: sm.id },
            data: { status: "INSTALLED", version: result.version ?? null, error: null },
          });
          installedNames.push(sm.mod.name);
        }
      } else {
        await db.serverMod.update({
          where: { id: sm.id },
          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
        });
        failedNames.push(sm.mod.name);
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
      await db.serverMod.update({
        where: { id: sm.id },
        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
      });
      failedNames.push(sm.mod.name);
    }
  }

  // One summary notification for the batch.
  const parts: string[] = [];
  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
  const anyOk = installedNames.length > 0 || removedNames.length > 0;
  const allFailed = !anyOk && failedNames.length > 0;

  await notify(
    server.userId,
    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
    `/dashboard/servers/${server.id}?tab=mods`
  );
}

// ===========================================================================
// Real install/remove — per-source adapters over SSH.
//
// Approach: the worker resolves a DIRECT download URL from the source's API, then
// SSHes into the game VM and has the VM itself `curl` the file into the game's
// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
// per-install state to track). Sources that need auth or per-repo handling
// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
// clear "install manually from <url>" note rather than faking success.
//
// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
// (Valheim) — which fully covers those three games' catalogs.
// ===========================================================================

type ModResult = { ok: boolean; version?: string; error?: string };
type ModRow = {
  gameFamily: string;
  source: string;
  sourceId: string | null;
  slug: string;
  name: string;
  url: string | null;
};
type SshServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

const CONNECT_TIMEOUT_MS = 15_000;
const EXEC_TIMEOUT_MS = 200_000; // downloads can be large

/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
function pascal(name: string): string {
  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
  return p || "Plugin";
}

/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
  switch (mod.source) {
    case "modrinth":
    case "spigotmc":
      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
    case "umod":
      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
    case "thunderstore":
      return { kind: "zip", folder: `nxeon-${mod.slug}` };
    default:
      return null; // github / nexus / curseforge / codefling / hangar — manual
  }
}

/** Resolve a direct download URL from the source's API (worker-side). */
async function resolveUrl(mod: ModRowFull): Promise<string | null> {
  const id = mod.sourceId ?? "";
  try {
    switch (mod.source) {
      case "umod":
        return `https://umod.org/plugins/${id}.cs`;
      case "spigotmc":
        return `https://api.spiget.org/v2/resources/${id}/download`;
      case "modrinth": {
        const loader = modrinthLoader(mod);
        const q = loader ? `?loaders=["${loader}"]` : "";
        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
        });
        if (!res.ok) return null;
        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
        const v = versions[0];
        if (!v) return null;
        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
      }
      case "thunderstore": {
        const [author, ...rest] = id.split("-");
        if (!rest.length) return null;
        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
        });
        if (!res.ok) return null;
        const pkg = (await res.json()) as { latest?: { download_url?: string } };
        return pkg.latest?.download_url ?? null;
      }
      default:
        return null;
    }
  } catch (e) {
    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
    return null;
  }
}

function modrinthLoader(mod: ModRowFull): string | null {
  // Prefer the mod's own loader target; fall back to the server's variant.
  const key = mod.appliesTo ?? mod.variant ?? "";
  const map: Record<string, string> = {
    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
  };
  return map[key] ?? null;
}

